"""docs/Modelisation is generated by the Python generator from this
repository: it must match what the current code would generate."""

from pathlib import Path

import pytest

from conftest import REPO_ROOT, assert_same_tree, run_script

PYTHON_SCRIPT = "generate_class_diagramm_python.py"
SELF_DOCS = REPO_ROOT / "docs" / "Modelisation"
EXCLUDE_OPTION = "--exclude"
OUT_OPTION = "-o"
EXCLUDES = ["tests/*"]
REGENERATE_COMMAND = (
    f"python {PYTHON_SCRIPT} . "
    + " ".join(f'{EXCLUDE_OPTION} "{pattern}"' for pattern in EXCLUDES)
    + f" {OUT_OPTION} docs/Modelisation"
)


def test_self_docs_match_the_current_code(tmp_path: Path):
    exclude_arguments = [argument for pattern in EXCLUDES for argument in (EXCLUDE_OPTION, pattern)]

    result = run_script(PYTHON_SCRIPT, REPO_ROOT, OUT_OPTION, tmp_path, *exclude_arguments, cwd=tmp_path)

    assert result.returncode == 0, f"{result.stdout}\n{result.stderr}"
    try:
        assert_same_tree(tmp_path, SELF_DOCS)
    except AssertionError as difference:
        pytest.fail(f"docs/Modelisation is out of date; regenerate it with:\n  {REGENERATE_COMMAND}\n\n{difference}")


def test_readme_documents_the_regeneration_command():
    readme = (REPO_ROOT / "README.md").read_text(encoding="utf-8")

    assert REGENERATE_COMMAND in readme
